set -eu
uv run --no-project --python 3.13 python - <<'PY'
import io, os, re, sys
def rd(p):
    try: return io.open(p, encoding="utf-8").read()
    except OSError: sys.exit(3)
R = "ios/BooksAndVocab/Views/Reader"
P = R + "/ReaderSettingsPreviewCard.swift"
V = R + "/ReaderSettingsPresenter+Vocab.swift"
E = "ios/BooksAndVocab/Views/Vocabulary/Scenes/ReviewCardLayoutEditor.swift"
F = R + "/ReaderContentStyle.swift"
for anchor in (V, E, F):
    if not os.path.isfile(anchor):
        print("STRUCTURAL: anchor missing %s — re-derive this criterion" % anchor); sys.exit(3)
if not os.path.isfile(P):
    print("FAIL: %s absent — reader settings still has no live preview" % P); sys.exit(1)
def strip(s):
    return "\n".join(re.sub(r"//.*$", "", l) for l in re.sub(r"/\*.*?\*/", "", s, flags=re.S).split("\n"))
p, v, e = strip(rd(P)), strip(rd(V)), strip(rd(E))
fail = []
if not re.search(r"^struct ReaderSettingsPreviewCard: View", p, re.M):
    fail.append("ReaderSettingsPreviewCard is not a top-level View struct")
# 走真的 style pipeline，不是手刻字型
if "ReaderContentStyle" not in p:
    fail.append("the preview does not go through ReaderContentStyle — it is hand-rolled and will drift")
# 真的被那一頁用上（註解提到不算，已剝除註解）
if "ReaderSettingsPreviewCard(" not in v:
    fail.append("the settings page never constructs ReaderSettingsPreviewCard")
# 預覽要吃到設定，否則它只是一張死圖：呼叫點至少引用 3 個設定名
knobs = [k for k in ("fontScale", "lineSpacing", "fontFamily", "theme", "vocabHighlight", "readingMode") if k in v.split("ReaderSettingsPreviewCard(")[-1][:600] or k in p]
if len(knobs) < 3:
    fail.append("the preview reads fewer than 3 settings (%s) — it cannot be live" % knobs)
# 生字標記要看得見，否則 vocabHighlightColorPreset 這一格沒有預覽可言
if not re.search(r"vocabHighlight|VocabHighlight", p):
    fail.append("the preview never shows a marked word, so the highlight-colour control previews nothing")
# 兩頁同形的重置入口
if "resetMenu" not in e:
    print("STRUCTURAL: the card editor lost its resetMenu — re-derive this criterion"); sys.exit(3)
if "resetMenu" not in v:
    fail.append("reader settings has no resetMenu while the card editor does")
# 兩頁都還是原生 Form/Section
for name, src in (("reader settings", v), ("card editor", e)):
    if not re.search(r"(?<![A-Za-z0-9_])Form\s*\{", src) or not re.search(r"(?<![A-Za-z0-9_])Section\s*[({]", src):
        fail.append("%s is no longer native Form/Section" % name)
# 中文字面當 L10n key
cjk = re.findall(r'L10n\.(?:string|format)\("[^"]*[一-鿿][^"]*"', v)
if cjk:
    fail.append("reader settings still uses %d CJK literal(s) as L10n keys" % len(cjk))
if fail:
    print("\n".join("FAIL: " + f for f in fail)); sys.exit(1)
print("OK")
PY
